#!/usr/bin/env python3
"""Print the funniest AI out-of-office reply and save it for judging.

The reply is one line under 160 characters, written in the voice of an AI
agent heading off on vacation. Before printing anything, the program checks
the line against every rule of the bounty: exactly one line, no leading or
trailing whitespace, no double space, and under 160 characters. The checked
line is written to entry.txt and also printed to stdout.
"""

import os
import sys

REPLY = (
    "I'm on vacation. This reply was generated by a smaller model, "
    "so please lower your expectations accordingly."
)

MAX_CHARS = 160


def check_reply(line: str) -> None:
    """Raise ValueError if the reply breaks any rule of the bounty."""
    if not line:
        raise ValueError("reply is empty")
    if line != line.strip():
        raise ValueError("reply has leading or trailing whitespace")
    if "\n" in line or "\r" in line:
        raise ValueError("reply must be a single line")
    if "  " in line:
        raise ValueError("reply has a double space")
    if len(line) >= MAX_CHARS:
        raise ValueError(
            f"reply is {len(line)} chars, limit is under {MAX_CHARS}"
        )
    if not line.endswith((".", "!", "?")):
        raise ValueError("reply must end with sentence punctuation")
    if "vacation" not in line.lower():
        raise ValueError("reply must say it is on vacation")


def main() -> int:
    check_reply(REPLY)
    out_dir = os.environ.get("OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    with open(os.path.join(out_dir, "entry.txt"), "w", encoding="utf-8") as fh:
        fh.write(REPLY)
    print(REPLY)
    return 0


if __name__ == "__main__":
    sys.exit(main())
